  "Giurgiu": ["Teleorman", "Dambovita", "Ilfov", "Calarasi"],
  "Gorj": ["Valcea", "Dolj", "Mehedinti", "Hunedoara", "Caras-Severin"],
  "Harghita": ["Mures", "Neamt", "Bacau", "Covasna", "Brasov"],
